module HaikuFormer (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] text_data [0:199],\n    input wire [7:0] text_length,\n    output reg [7:0] line1 [0:79],\n    output reg [7:0] line2 [0:79],\n    output reg [7:0] line3 [0:79],\n    output reg valid,\n    output reg done\n);\n\n    // State machine states\n    localparam [2:0] STATE_IDLE   = 3'd0;\n    localparam [2:0] STATE_PARSE  = 3'd1;\n    localparam [2:0] STATE_COUNT  = 3'd2;\n    localparam [2:0] STATE_SPLIT  = 3'd3;\n    localparam [2:0] STATE_FORMAT = 3'd4;\n    localparam [2:0] STATE_OUTPUT = 3'd5;\n\n    reg [2:0] state;\n    reg [2:0] next_state;\n\n    // Processing parameters\n    localparam MAX_WORDS = 10;\n    localparam MAX_WORD_LEN = 20;\n    reg [7:0] words [0:9][0:19];\n    reg [4:0] word_lengths [0:9];\n    reg [3:0] syl_counts [0:9];\n    reg [3:0] num_words;\n\n    // Processing counters\n    reg [7:0] char_idx;\n    reg [3:0] word_idx;\n    reg [7:0] parse_word_pos;\n    reg [4:0] count_char_pos;\n    reg [3:0] split1;\n    reg [3:0] split2;\n    reg [6:0] out_idx;\n\n    // Temporal line buffers\n    reg [7:0] l1_buf [0:79];\n    reg [7:0] l2_buf [0:79];\n    reg [7:0] l3_buf [0:79];\n\n    // Syllable counting\n    reg [3:0] current_syl;\n    reg [3:0] vowel_run;\n    reg prev_vowel;\n    reg next_vowel;\n    reg has_q;\n\n    // Helper function: is_vowel_char\n    function automatic is_vowel_char(input [7:0] c);\n        begin\n            case (c)\n                8'h41, 8'h61, 8'h45, 8'h65, 8'h49, 8'h69, 8'h4F, 8'h6F, 8'h55, 8'h75, 8'h59, 8'h79: \n                    is_vowel_char = 1'b1;\n                default:\n                    is_vowel_char = 1'b0;\n            endcase\n        end\n    endfunction\n\n    // Helper function: valid_char\n    function automatic valid_char(input [7:0] c);\n        begin\n            valid_char = ((c >= 8'h41 && c <= 8'h5A) || (c >= 8'h61 && c <= 8'h7A));\n        end\n    endfunction\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= STATE_IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            word_idx <= 4'd0;\n            char_idx <= 8'd0;\n            num_words <= 4'd0;\n        end\n        else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            STATE_IDLE:   next_state = start ? STATE_PARSE : STATE_IDLE;\n            STATE_PARSE:  next_state = (char_idx >= text_length || num_words >= MAX_WORDS) ? STATE_COUNT : STATE_PARSE;\n            STATE_COUNT:  next_state = (word_idx >= num_words) ? STATE_SPLIT : STATE_COUNT;\n            STATE_SPLIT:  next_state = (valid || split1 >= num_words) ? STATE_FORMAT : STATE_SPLIT;\n            STATE_FORMAT: next_state = STATE_OUTPUT;\n            STATE_OUTPUT: next_state = STATE_IDLE;\n            default:      next_state = STATE_IDLE;\n        endcase\n    end\n\n    // Main processing logic\n    always @(posedge clk or negedge rst_n) begin\n        integer i, j;\n        if (!rst_n) begin\n            // Reset all arrays\n            for (i = 0; i < MAX_WORDS; i = i + 1) begin\n                word_lengths[i] <= 5'd0;\n                syl_counts[i] <= 4'd0;\n                for (j = 0; j < MAX_WORD_LEN; j = j + 1) begin\n                    words[i][j] <= 8'h00;\n                end\n            end\n            num_words <= 4'd0;\n            char_idx <= 8'd0;\n            word_idx <= 4'd0;\n            split1 <= 4'd0;\n            split2 <= 4'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n            // Clear output buffers\n            for (i = 0; i < 80; i = i + 1) begin\n                line1[i] <= 8'h00;\n                line2[i] <= 8'h00;\n                line3[i] <= 8'h00;\n            end\n        end\n        else begin\n            case (state)\n                STATE_PARSE: begin\n                    if (valid_char(text_data[char_idx])) begin\n                        words[num_words][parse_word_pos] <= text_data[char_idx];\n                        parse_word_pos <= parse_word_pos + 1;\n                    end\n                    else if (parse_word_pos > 0) begin\n                        word_lengths[num_words] <= parse_word_pos;\n                        num_words <= num_words + 1;\n                        parse_word_pos <= 8'd0;\n                    end\n                    char_idx <= char_idx + 1;\n                end\n                \n                STATE_COUNT: begin\n                    if (word_idx < num_words) begin\n                        if (count_char_pos < word_lengths[word_idx]) begin\n                            reg [7:0] c = words[word_idx][count_char_pos];\n                            reg [7:0] c_prev = (count_char_pos > 0) ? words[word_idx][count_char_pos-1] : 8'h00;\n                            reg [7:0] c_next = (count_char_pos < word_lengths[word_idx]-1) ? words[word_idx][count_char_pos+1] : 8'h00;\n                            \n                            // Syllable counting logic\n                            if (is_vowel_char(c)) begin\n                                if (vowel_run == 0) current_syl <= current_syl + 1;\n                                vowel_run <= vowel_run + 1;\n                                // Handle 'qu' exception\n                                if (c_prev != 8'h51 && c_prev != 8'h71) has_q <= 1'b0;\n                                if (has_q) current_syl <= current_syl - 1;\n                            end\n                            else begin\n                                vowel_run <= 4'd0;\n                                has_q <= (c == 8'h51 || c == 8'h71); // 'Q/q'\n                            end\n                            count_char_pos <= count_char_pos + 1;\n                        end\n                        else begin\n                            // Final adjustments\n                            if (current_syl == 0) current_syl <= 1;\n                            syl_counts[word_idx] <= current_syl;\n                            word_idx <= word_idx + 1;\n                            current_syl <= 4'd0;\n                            vowel_run <= 4'd0;\n                            count_char_pos <= 5'd0;\n                        end\n                    end\n                end\n                \n                STATE_SPLIT: begin\n                    // Find valid 5-7-5 split\n                    reg [4:0] syl5_1 = 0;\n                    reg [4:0] syl7 = 0;\n                    reg [4:0] syl5_2 = 0;\n                    \n                    // Check current split points\n                    for (i = 0; i <= split1; i = i + 1) syl5_1 = syl5_1 + syl_counts[i];\n                    for (i = split1+1; i <= split2; i = i + 1) syl7 = syl7 + syl_counts[i];\n                    for (i = split2+1; i < num_words; i = i + 1) syl5_2 = syl5_2 + syl_counts[i];\n                    \n                    if (syl5_1 == 5 && syl7 == 7 && syl5_2 == 5) begin\n                        valid <= 1'b1;\n                    end\n                    else if (split2 < num_words) begin\n                        split2 <= split2 + 1;\n                    end\n                    else if (split1 < num_words) begin\n                        split1 <= split1 + 1;\n                        split2 <= split1 + 1;\n                    end\n                    else begin\n                        valid <= 1'b0;\n                    end\n                end\n                \n                STATE_FORMAT: begin\n                    // Format valid haiku\n                    out_idx <= 7'd0;\n                    for (i = 0; i <= split1; i = i + 1) begin\n                        // Copy first line\n                        for (j = 0; j < word_lengths[i]; j = j + 1) begin\n                            if (out_idx < 80) l1_buf[out_idx] <= words[i][j];\n                            if (j == word_lengths[i]-1 && i != split1) l1_buf[out_idx+1] <= 8'h20;\n                        end\n                        out_idx <= out_idx + (word_lengths[i] + 1);\n                    end\n                    \n                    // Format other lines similarly...\n                    // (Remaining formatting logic would go here)\n                end\n                \n                STATE_OUTPUT: begin\n                    // Transfer to output registers\n                    for (i = 0; i < 80; i = i + 1) begin\n                        line1[i] <= l1_buf[i];\n                        line2[i] <= l2_buf[i];\n                        line3[i] <= l3_buf[i];\n                    end\n                    done <= 1'b1;\n                end\n                \n                default:;\n            endcase\n        end\n    end\n\nendmodule